-- services/common/data/2026-07_semantic_core_import.sql
-- Разовый импорт полного семантического ядра из файла
-- 'все запросы из СЯ для БД.xlsx' (лист 'Семантическое ядро').
-- Источник: 4673 строк в файле -> 4087 уникальных непустых запросов.
--
-- Маппинг колонок файла -> common.requests:
--   'Запросы'                              -> request
--   'Хаб / Название раздела на сайте'      -> hub_id   (через common.hubs, часть значений переименована/добавлена ниже)
--   'Кластер'                               -> cluster_id (через common.clusters, все 39 значений новые)
--   'Группа по ТопВизеру'                   -> cluster_topvisor_id (через common.clusters_topvisor,
--                                              project_topvisor_id IN (7093082, 0) — 0 = общий 'Не отслеживается')
--   'Тип выдачи Яндекс'                     -> type_request_id (через common.type_request)
--
-- Политика связей: строка добавляется в common.requests по одному лишь тексту запроса.
-- Если какая-то из 4 связей не находится в справочнике — соответствующее поле остаётся NULL,
-- строка всё равно импортируется (не пропускается).
--
-- Безопасно перезапускать: переименование хабов идёт по hub_id (идемпотентно),
-- добавление в hubs/clusters — через WHERE NOT EXISTS, финальная вставка в
-- common.requests — через ON CONFLICT (request) DO NOTHING. Существующие строки
-- common.requests (и их текущие hub_id/cluster_id/cluster_topvisor_id/type_request_id)
-- никогда не перезаписываются.

BEGIN;

-- 1. Переименование существующих hub_name (id сохраняется)
UPDATE common.hubs SET hub_name = 'DDoS' WHERE hub_id = 1;
UPDATE common.hubs SET hub_name = 'Сайт' WHERE hub_id = 2;
UPDATE common.hubs SET hub_name = 'Сети' WHERE hub_id = 3;
UPDATE common.hubs SET hub_name = 'Хостинг' WHERE hub_id = 4;
UPDATE common.hubs SET hub_name = 'VDS' WHERE hub_id = 5;
UPDATE common.hubs SET hub_name = 'DS / Дедик / Выделенный' WHERE hub_id = 6;
UPDATE common.hubs SET hub_name = 'Боты' WHERE hub_id = 7;
UPDATE common.hubs SET hub_name = 'WAF' WHERE hub_id = 8;

-- 2. Новые значения hub_name (остальные значения из колонки 'Хаб' файла)
INSERT INTO common.hubs (hub_name)
SELECT v.name FROM (VALUES
    ('DNS'),
    ('Web-технологии'),
    ('Доп.Услуги'),
    ('Информационная безопасность'),
    ('Кибербезопасность'),
    ('Киберугрозы'),
    ('Уязвимости'),
    ('Фильтрация')
) AS v(name)
WHERE NOT EXISTS (SELECT 1 FROM common.hubs h WHERE h.hub_name = v.name);

-- 3. Новые значения cluster_name (все значения колонки 'Кластер' файла - в common.clusters их не было)
INSERT INTO common.clusters (cluster_name)
SELECT v.name FROM (VALUES
    ('Cloudflare'),
    ('Анализ'),
    ('Балансировка'),
    ('Без защиты (не целевой)'),
    ('Безопасность'),
    ('Бесплатно'),
    ('Векторы атак'),
    ('Виды'),
    ('Вредоносные (Действие/Намерение)'),
    ('Вредоносные (Покупка/Заказ)'),
    ('Вредоносные (Софт/Скрипты)'),
    ('Вредоносные (Цели: IP/Телефон/Сеть)'),
    ('Гейминг'),
    ('Готовое решение'),
    ('Заказ атаки?'),
    ('Защита'),
    ('Как'),
    ('Как работает'),
    ('Какие'),
    ('Конкретный тип атаки'),
    ('Маршрутизация'),
    ('Не целевые'),
    ('Новости'),
    ('Общее понятие DDoS'),
    ('Отключить'),
    ('Отличие'),
    ('Поиск'),
    ('Последствия'),
    ('Правовые/Юридические'),
    ('Причины'),
    ('Радар'),
    ('Распределение'),
    ('Руководство'),
    ('Сегментация'),
    ('Справка / Терминология'),
    ('Тест'),
    ('Цели'),
    ('Цены'),
    ('Что')
) AS v(name)
WHERE NOT EXISTS (SELECT 1 FROM common.clusters c WHERE c.cluster_name = v.name);

-- 4. Staging: сырые строки файла как есть
CREATE TEMP TABLE _semantic_core_import (
    seq INTEGER,
    request TEXT,
    hub_name TEXT,
    cluster_name TEXT,
    topvisor_group_name TEXT,
    type_name TEXT
);

