-- 5. Финальная вставка: LEFT JOIN на все 4 справочника, текст запроса - единственное обязательное поле
INSERT INTO common.requests (request, hub_id, cluster_id, cluster_topvisor_id, type_request_id)
SELECT DISTINCT ON (s.request)
    s.request, h.hub_id, c.cluster_id, ct.cluster_topvisor_id, tr.type_request_id
FROM _semantic_core_import s
LEFT JOIN common.hubs h ON h.hub_name = s.hub_name
LEFT JOIN common.clusters c ON c.cluster_name = s.cluster_name
LEFT JOIN common.clusters_topvisor ct ON ct.cluster_topvisor_name = s.topvisor_group_name
    AND ct.project_topvisor_id IN (7093082, 0)
LEFT JOIN common.type_request tr ON tr.name_type = s.type_name
ORDER BY s.request, s.seq
ON CONFLICT (request) DO NOTHING;

DROP TABLE _semantic_core_import;

COMMIT;
